import json
from urllib.parse import quote, urlencode


class ApiError(Exception):
    def __init__(self, status, code, message, request_id):
        super().__init__(f"{status} {code}: {message} (request {request_id})")
        self.status = status
        self.code = code
        self.message = message
        self.request_id = request_id


class BooksClient:
    def __init__(self, transport, base_url, api_key, timeout=10):
        self.transport = transport
        self.base_url = base_url.rstrip("/")
        self.api_key = api_key
        self.timeout = timeout

    def request(self, method, path, query=None, body=None):
        url = self.base_url + path
        pairs = []
        for name, value in (query or {}).items():
            if value is None:
                continue
            pairs.append((name, ("true" if value else "false") if isinstance(value, bool) else str(value)))
        if pairs:
            url += "?" + urlencode(pairs)
        headers = {"Accept": "application/json", "Authorization": f"Bearer {self.api_key}"}
        data = None
        if body is not None:
            headers["Content-Type"] = "application/json"
            data = json.dumps(body).encode("utf-8")

        status, resp_headers, raw = self.transport.send(method, url, headers, data, self.timeout)
        lower = {k.lower(): v for k, v in resp_headers.items()}
        request_id = lower.get("x-request-id")
        is_json = lower.get("content-type", "").split(";")[0].strip().lower() == "application/json"

        payload = None
        parse_failed = False
        if raw and is_json:
            try:
                payload = json.loads(raw.decode("utf-8"))
            except (UnicodeDecodeError, json.JSONDecodeError):
                parse_failed = True

        if 200 <= status < 300:
            if parse_failed:
                raise ApiError(status, "invalid_json", "the response was not valid JSON", request_id)
            return payload

        code, message = None, f"HTTP {status}"
        error = payload.get("error") if isinstance(payload, dict) else None
        if isinstance(error, dict):
            code = error.get("code", code)
            message = error.get("message", message)
        raise ApiError(status, code, message, request_id)

    def list_books(self, author=None, limit=None):
        return self.request("GET", "/books", {"author": author, "limit": limit})["items"]

    def get_book(self, book_id):
        try:
            return self.request("GET", "/books/" + quote(str(book_id), safe=""))
        except ApiError as e:
            if e.status == 404:
                return None
            raise

    def create_book(self, title, year=None):
        body = {"title": title}
        if year is not None:
            body["year"] = year
        return self.request("POST", "/books", body=body)

    def delete_book(self, book_id):
        try:
            self.request("DELETE", "/books/" + quote(str(book_id), safe=""))
            return True
        except ApiError as e:
            if e.status == 404:
                return False
            raise

