import json

class FakeTransport:
    def __init__(self, *responses):
        self.responses = list(responses)
        self.sent = []
    def send(self, method, url, headers, body, timeout):
        self.sent.append({"method": method, "url": url, "headers": dict(headers), "body": body, "timeout": timeout})
        return self.responses.pop(0)

def ok(data, status=200, **headers):
    h = {"Content-Type": "application/json"}
    h.update(headers)
    return (status, h, json.dumps(data).encode())

def catch(fn, *args, **kwargs):
    try:
        fn(*args, **kwargs)
    except ApiError as e:
        return e
    return None

@test("a GET request")
def _():
    t = FakeTransport(ok({"id": 7, "title": "Dune"}))
    c = BooksClient(t, "https://api.example.com/v1/", "k123", timeout=5)
    check_eq(c.get_book(7), {"id": 7, "title": "Dune"})
    s = t.sent[0]
    check_eq(s["method"], "GET")
    check_eq(s["url"], "https://api.example.com/v1/books/7")
    check_eq(s["headers"], {"Accept": "application/json", "Authorization": "Bearer k123"})
    check_eq(s["body"], None)
    check_eq(s["timeout"], 5)

@test("listing with a query")
def _():
    t = FakeTransport(ok({"items": [{"id": 1}]}), ok({"items": []}))
    c = BooksClient(t, "https://api.example.com", "k")
    check_eq(c.list_books(author="Le Guin & co", limit=5), [{"id": 1}])
    check_eq(t.sent[0]["url"], "https://api.example.com/books?author=Le+Guin+%26+co&limit=5")
    check_eq(c.list_books(), [])
    check_eq(t.sent[1]["url"], "https://api.example.com/books")

@test("creating sends JSON")
def _():
    t = FakeTransport(ok({"id": 9, "title": "Kindred"}, 201), ok({"id": 10, "title": "X", "year": 1979}, 201))
    c = BooksClient(t, "https://h", "k")
    check_eq(c.create_book("Kindred"), {"id": 9, "title": "Kindred"})
    check_eq(t.sent[0]["method"], "POST")
    check_eq(t.sent[0]["headers"]["Content-Type"], "application/json")
    check_eq(json.loads(t.sent[0]["body"]), {"title": "Kindred"})
    c.create_book("X", year=1979)
    check_eq(json.loads(t.sent[1]["body"]), {"title": "X", "year": 1979})

@test("escaping the id")
def _():
    t = FakeTransport(ok({}))
    BooksClient(t, "https://h", "k").get_book("a/b c")
    check_eq(t.sent[0]["url"], "https://h/books/a%2Fb%20c")

@test("404 is a result for get and delete")
def _():
    t = FakeTransport((404, {}, b""), (204, {}, b""), (404, {"Content-Type": "application/json"}, b'{"error": {"code": "not_found"}}'))
    c = BooksClient(t, "https://h", "k")
    check_eq(c.get_book(1), None)
    check_eq(c.delete_book(1), True)
    check_eq(t.sent[1]["method"], "DELETE")
    check_eq(c.delete_book(1), False)

@test("errors carry the details")
def _():
    body = b'{"error": {"code": "invalid_year", "message": "year must be between 0 and 2100"}}'
    t = FakeTransport((422, {"content-type": "application/json", "x-request-id": "req-1"}, body))
    e = catch(BooksClient(t, "https://h", "k").create_book, "A", 3000)
    check(e is not None, "expected ApiError")
    if e:
        check_eq((e.status, e.code, e.message, e.request_id), (422, "invalid_year", "year must be between 0 and 2100", "req-1"))

@test("errors without a JSON body")
def _():
    t = FakeTransport((502, {"Content-Type": "text/html"}, b"<h1>Bad gateway</h1>"), (500, {}, b""))
    c = BooksClient(t, "https://h", "k")
    e = catch(c.get_book, 1)
    check(e is not None and (e.status, e.code, e.message, e.request_id) == (502, None, "HTTP 502", None))
    e = catch(c.list_books)
    check(e is not None and e.message == "HTTP 500")

@test("a success that is not valid JSON")
def _():
    t = FakeTransport((200, {"Content-Type": "application/json", "X-Request-Id": "r9"}, b"{oops"))
    e = catch(BooksClient(t, "https://h", "k").get_book, 1)
    check(e is not None and (e.status, e.code, e.request_id) == (200, "invalid_json", "r9"))

